-- Table structure for table `device`
--

DROP TABLE IF EXISTS `device`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device` (
  `device_id` int unsigned NOT NULL AUTO_INCREMENT,
  `device_name` varchar(45) DEFAULT NULL,
  `device_serial` varchar(100) DEFAULT NULL,
  `dev_cat_id` int DEFAULT NULL,
  `dev_mod_id` int DEFAULT NULL,
  `dev_unit_id` int DEFAULT NULL,
  `device_setting` varchar(255) DEFAULT NULL,
  `expire_date` varchar(50) DEFAULT NULL,
  `device_protocol` varchar(45) DEFAULT NULL,
  `area_id` int DEFAULT NULL,
  `ip_addr` varchar(45) DEFAULT NULL,
  `ip_port` varchar(45) DEFAULT NULL,
  `is_ready` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0：未准备好，1：已准备好',
  `status` int DEFAULT '0' COMMENT '0:无效；1：可用；2：繁忙；3：故障',
  `error_msg` varchar(100) DEFAULT NULL,
  `device_desc` varchar(255) DEFAULT NULL,
  `driver_id` varchar(45) DEFAULT NULL COMMENT '设备连接的驱动Id',
  `deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` varchar(45) DEFAULT NULL,
  `updated_by` varchar(45) DEFAULT NULL,
  `area_ids` varchar(255) DEFAULT '[]' COMMENT '站位列表json字符串',
  `desc` varchar(200) DEFAULT NULL,
  `remark` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `show_military` int DEFAULT '1' COMMENT '是否显示给军代表',
  PRIMARY KEY (`device_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1213 DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `device`
--

LOCK TABLES `device` WRITE;
/*!40000 ALTER TABLE `device` DISABLE KEYS */;
